def solve(K, s):
    # Для каждого разбиения: m точек справа, число раскрасок m + C(m,2) = C(m+1,2)
    # Суммируем по m от s до n-s, ищем n с суммой, равной K
    for n in range(1, 500):
        total = 0
        for m in range(s, n - s + 1):
            total += m + comb(m, 2)
        if total == K:
            return n
    return -1
